{
    Harness h;
    h.handshake();
    h.deliver("pick_attachment", json{{"kind", "image"}});
    const json* error = h.last_of_type("bridge_error");
    REQUIRE(error != nullptr);
    CHECK((*error)["payload"]["code"] == "unsupported");
    CHECK(h.last_of_type("attachment_updated") == nullptr);
}

