{
    WorkEntry entry;
    entry.kind  = kind;
    entry.title = title;
    // A slice the chat's model started sits right below the call that started
    // it, where its reply told the model the person sees it, even when the
    // run's first progress arrives after the model has replied.
    if (kind == "slice")
